{"cards": [{"node_code": "N_04c2240db1126c97", "definition": "研究木材宏观与微观解剖结构，包括年轮、导管、木射线、细胞形态及纹理特征，揭示其各向异性来源及结构组成规律。", "boundary": "本节点聚焦于木材正常的、固有的解剖构造特征。涵盖从宏观纹理识别到微观细胞结构的描述。与“缺陷”的区别在于，本节点研究的是木材正常的结构组成，而非异常或损伤部分；与“木材分类”的区别在于，本节点侧重结构形态描述，而非物种归属。", "includes": ["木材宏观构造（年轮、纹理、早晚材）与微观构造（细胞类型、排列）", "木材解剖学基础及构造特征对工程性能的基础影响"], "excludes": ["木材节子、裂纹、腐朽等异常形态的识别与成因（归入缺陷）", "基于构造特征的树种鉴定与分类体系（归入木材分类）"], "sibling_distinctions": [{"other_code": "N_ccc0266c002d585a", "rule": "本节点研究木材正常的解剖结构组成；兄弟节点研究偏离正常结构的异常形态（缺陷）。"}, {"other_code": "N_21f1ca9a4426d590", "rule": "本节点侧重结构形态的描述与机理；兄弟节点侧重物种的识别、命名与分类系统。"}], "cross_boundary_rule": ""}, {"node_code": "N_ccc0266c002d585a", "definition": "研究木材中天然或后天形成的异常结构（如节子、斜纹、裂纹、腐朽、虫眼）的形态识别、成因分析及对材料完整性的影响。", "boundary": "本节点聚焦于木材中偏离正常构造的异常部分。涵盖缺陷的形态学分类、产生机理（生物、物理、化学）及其分布规律。与“构造”的区别在于，本节点关注“非正常”或“损伤”特征；与“木材分类”的区别在于，本节点不关注物种归属，而关注个体材料的瑕疵。", "includes": ["天然缺陷（节子、斜纹、死节）与后天缺陷（腐朽、虫蛀、机械损伤）的识别", "缺陷的成因分析、分布规律及其对木材工程适用性的定性影响"], "excludes": ["木材正常的解剖构造描述（归入构造）", "缺陷导致的具体力学强度折减系数计算（归入木材力学性能）"], "sibling_distinctions": [{"other_code": "N_04c2240db1126c97", "rule": "本节点研究异常形态（缺陷）；兄弟节点研究正常解剖结构（构造）。"}, {"other_code": "N_21f1ca9a4426d590", "rule": "本节点关注个体材料的瑕疵特征；兄弟节点关注物种层面的分类与鉴定。"}], "cross_boundary_rule": ""}, {"node_code": "N_21f1ca9a4426d590", "definition": "研究木材的树种鉴定、分类系统（如针叶材/阔叶材、软木/硬木）及基于形态特征的物种识别方法，建立工程用材的物种基础。", "boundary": "本节点聚焦于木材的物种归属与分类体系。涵盖植物学分类在工程木材中的应用、常见工程树种的识别特征及分类标准。与“构造”的区别在于，本节点侧重“是什么树种”，而非“结构长什么样”；与“缺陷”的区别在于，本节点关注物种固有属性，而非个体异常。", "includes": ["木材的植物学分类体系及工程分类（针叶/阔叶、软/硬木）", "常见工程树种的形态识别特征、产地分布及分类标准"], "excludes": ["木材微观细胞结构的详细解剖描述（归入构造）", "木材个体中节子、裂纹等异常形态的识别（归入缺陷）"], "sibling_distinctions": [{"other_code": "N_04c2240db1126c97", "rule": "本节点侧重物种鉴定与分类系统；兄弟节点侧重解剖结构的形态描述。"}, {"other_code": "N_ccc0266c002d585a", "rule": "本节点关注物种层面的固有属性；兄弟节点关注个体层面的异常瑕疵。"}], "cross_boundary_rule": ""}]}
